command:
$ErrorActionPreference = 'Stop'
$forgeRoot = (Get-Location).Path
. '.forge-codex/instructions/scripts/Common.ps1'
& '.forge-codex/instructions/scripts/Verify-Ledger.ps1' -WorkspaceRoot $forgeRoot
& '.forge-codex/instructions/scripts/Validate-NoPython.ps1' -WorkspaceRoot $forgeRoot
& '.forge-codex/instructions/scripts/Validate-NoAttribution.ps1' -WorkspaceRoot $forgeRoot
& '.forge-codex/instructions/scripts/Validate-McpParity.ps1' -WorkspaceRoot $forgeRoot -ActualToolSnapshot (Join-Path $forgeRoot 'tests/fixtures/Mcp/mcp-tools-semantic-golden.json')
$forgeEvidenceRelative = '.forge-codex/state/evidence/P14/shared-home-role-concurrency-checkpoint.json'
$forgeEvidencePath = Join-Path $forgeRoot $forgeEvidenceRelative
$forgeEvidence = Get-Content -Raw -LiteralPath $forgeEvidencePath | ConvertFrom-Json
if ($forgeEvidence.status -ne 'passed' -or $forgeEvidence.gate_status -ne 'open') { throw 'P14 shared-home checkpoint status is invalid.' }
if ($forgeEvidence.measured_result.focused_ctest_passed -ne 2 -or $forgeEvidence.measured_result.process_snapshot_assertions -ne 2529 -or $forgeEvidence.measured_result.persistence_tests_passed -ne 62) { throw 'P14 shared-home measured result is invalid.' }
if ($forgeEvidence.measured_result.peak_simultaneous_processes -ne 2 -or $forgeEvidence.measured_result.presence_count_fallback_after_primary_exit -ne 1 -or $forgeEvidence.measured_result.registry_projects -ne 1 -or $forgeEvidence.measured_result.registry_aliases -ne 1) { throw 'P14 shared-home concurrency result is invalid.' }
$forgeRecordRelative = [string]$forgeEvidence.command_record
$forgeRecordPath = Join-Path $forgeRoot $forgeRecordRelative
$forgeRecord = Get-Content -Raw -LiteralPath $forgeRecordPath | ConvertFrom-Json
if ($forgeRecord.exit_code -ne 0 -or $forgeRecord.timed_out) { throw 'The authoritative shared-home command did not pass.' }
foreach ($forgeStreamName in @('stdout','stderr')) {
  $forgeStreamRelative = [string]$forgeRecord.$forgeStreamName
  $forgeStreamPath = Join-Path $forgeRoot $forgeStreamRelative
  if (-not (Test-Path -LiteralPath $forgeStreamPath -PathType Leaf)) { throw "Missing command stream: $forgeStreamRelative" }
  $forgeExpectedHash = [string]$forgeRecord."${forgeStreamName}_sha256"
  $forgeActualHash = Get-FileSha256 -Path $forgeStreamPath
  if ($forgeActualHash -ne $forgeExpectedHash) { throw "Command stream hash mismatch: $forgeStreamRelative" }
}
foreach ($forgeArtifact in $forgeEvidence.artifacts) {
  $forgeArtifactPath = Join-Path $forgeRoot ([string]$forgeArtifact.path)
  $forgeArtifactItem = Get-Item -LiteralPath $forgeArtifactPath
  if ($forgeArtifactItem.Length -ne [int64]$forgeArtifact.bytes) { throw "Artifact size mismatch: $($forgeArtifact.path)" }
  if ((Get-FileSha256 -Path $forgeArtifactPath) -ne [string]$forgeArtifact.sha256) { throw "Artifact hash mismatch: $($forgeArtifact.path)" }
}
foreach ($forgeSource in $forgeEvidence.source_evidence) {
  $forgeSourcePath = Join-Path $forgeRoot ([string]$forgeSource.path)
  if ((Get-FileSha256 -Path $forgeSourcePath) -ne [string]$forgeSource.sha256) { throw "Source hash mismatch: $($forgeSource.path)" }
}
$forgeLastTest = Get-Content -Raw -LiteralPath (Join-Path $forgeRoot 'out/build/windows-msvc-x64/Testing/Temporary/LastTest.log')
if ($forgeLastTest -notmatch 'MCP serve process snapshot tests passed: 2529 assertions' -or $forgeLastTest -notmatch '62/62 persistence tests passed' -or $forgeLastTest -notmatch '100% tests passed') { throw 'CTest output does not contain the qualified assertion and test totals.' }
$forgeRunState = Get-Content -Raw -LiteralPath (Join-Path $forgeRoot '.forge-codex/state/run-state.json') | ConvertFrom-Json
$forgeP14 = $forgeRunState.phases | Where-Object id -eq 'P14'
$forgeG14 = $forgeRunState.gates | Where-Object id -eq 'G14'
if ($forgeRunState.active_phase -ne 'P14' -or $forgeRunState.active_role -ne 'builder' -or $forgeP14.status -ne 'in_progress' -or $forgeG14.status -ne 'in_progress') { throw 'Run-state phase or gate status is invalid.' }
foreach ($forgeExpectedEvidence in @($forgeRecordRelative,$forgeEvidenceRelative)) {
  if ($forgeExpectedEvidence -notin $forgeP14.evidence -or $forgeExpectedEvidence -notin $forgeG14.evidence) { throw "Run-state is missing checkpoint evidence: $forgeExpectedEvidence" }
}
$forgeNamespaceText = Get-Content -Raw -LiteralPath (Join-Path $forgeRoot 'src/Persistence/Windows/Detail/DatabaseNamespaceLease.cpp')
if ($forgeNamespaceText -notmatch 'constexpr ULONG DirectoryShare = FILE_SHARE_READ \| FILE_SHARE_WRITE;' -or $forgeNamespaceText -notmatch 'MaximumDirectoryComponentOpenWait = std::chrono::milliseconds\{500\}' -or $forgeNamespaceText -notmatch 'Domain::ErrorCodes::DatabaseBusy') { throw 'Namespace retry or pinning policy is invalid.' }
$forgeTextFiles = @('.forge-codex/state/evidence/P14/shared-home-role-concurrency-checkpoint.json','.forge-codex/state/run-state.json','src/Persistence/Windows/Detail/DatabaseNamespaceLease.cpp','tests/Persistence/DatabaseConcurrencyTests.cpp','tests/Mcp/McpServeProcessSnapshotTests.cpp')
foreach ($forgeTextRelative in $forgeTextFiles) {
  $forgeBytes = [IO.File]::ReadAllBytes((Join-Path $forgeRoot $forgeTextRelative))
  if ($forgeBytes.Length -ge 3 -and $forgeBytes[0] -eq 0xEF -and $forgeBytes[1] -eq 0xBB -and $forgeBytes[2] -eq 0xBF) { throw "UTF-8 BOM found: $forgeTextRelative" }
  $forgeText = [Text.Encoding]::UTF8.GetString($forgeBytes)
  if ([regex]::IsMatch($forgeText,'(?<!\r)\n')) { throw "Bare LF found: $forgeTextRelative" }
}
git diff --check
if ($LASTEXITCODE -ne 0) { throw 'git diff --check failed.' }
Write-Host 'P14 shared-home checkpoint integrity passed: 2/2 focused CTest tests, 2529 MCP assertions, 62/62 persistence tests, presence 2-to-1, one project alias, 53 tools.'
